#[inline]
fn destack_gpu_adapter_open_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::GpuAdapterHandle,
    id: NativeStringRef,
) -> RuntimeResult<()> {
    let _ = &id;

    binding.trace().run_binding_without_context(
        GPU_ADAPTER_OPEN,
        binding.replay_payload_for(GPU_ADAPTER_OPEN)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_gpu_adapter_open(binding, out, id)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_gpu_adapter_open(binding, out, id)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: resource::GpuAdapterHandle = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = GpuAdapterOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    GpuAdapterOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

