#[inline]
fn destack_gpu_device_open_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::GpuDeviceHandle,
    adapter: resource::GpuAdapterHandle,
    options: GpuDeviceOptions,
) -> RuntimeResult<()> {
    let _ = (&adapter, &options);

    binding.trace().run_binding_without_context(
        GPU_DEVICE_OPEN,
        binding.replay_payload_for(GPU_DEVICE_OPEN)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_gpu_device_open(binding, out, adapter, options)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_gpu_device_open(binding, out, adapter, options)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: resource::GpuDeviceHandle = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = GpuDeviceOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    GpuDeviceOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

