#[inline]
fn destack_gpu_device_pop_error_scope_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut GpuCapturedError,
    device: resource::GpuDeviceHandle,
    timeoutns: u64,
) -> RuntimeResult<()> {
    let _ = (&device, &timeoutns);

    binding.trace().run_binding_without_context(
        GPU_DEVICE_POP_ERROR_SCOPE,
        binding.replay_payload_for(GPU_DEVICE_POP_ERROR_SCOPE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_gpu_device_pop_error_scope(binding, out, device, timeoutns)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_gpu_device_pop_error_scope(
                    binding, out, device, timeoutns,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: GpuCapturedError = unsafe { out.read() };
                let result_recorded_message = if let Some(value) = result_value.message {
                    let result_recorded_message_inner = unsafe { value.as_str()? }.to_string();
                    Some(result_recorded_message_inner)
                } else {
                    None
                };
                let result_recorded_backend_code = if let Some(value) = result_value.backend_code {
                    let result_recorded_backend_code_inner = value;
                    Some(result_recorded_backend_code_inner)
                } else {
                    None
                };
                let result_recorded = GpucapturederrorReplayRecord {
                    message: result_recorded_message,
                    backend_code: result_recorded_backend_code,
                };
                let payload = GpuDevicePopErrorScopeReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    GpuDevicePopErrorScopeReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_message = if let Some(value) = value.message {
                        let value_native_message_inner = binding.store_string_owned(value);
                        Some(value_native_message_inner)
                    } else {
                        None
                    };
                    let value_native_backend_code = if let Some(value) = value.backend_code {
                        let value_native_backend_code_inner = value;
                        Some(value_native_backend_code_inner)
                    } else {
                        None
                    };
                    let value_native = GpuCapturedError {
                        message: value_native_message,
                        backend_code: value_native_backend_code,
                    };
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

