#[inline]
fn destack_gpu_pipeline_shader_compilation_info_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut GpuCompilationInfo,
    handle: resource::GpuShaderHandle,
    timeoutns: u64,
) -> RuntimeResult<()> {
    let _ = (&handle, &timeoutns);

    binding.trace().run_binding_without_context(
        GPU_PIPELINE_SHADER_COMPILATION_INFO,
        binding.replay_payload_for(GPU_PIPELINE_SHADER_COMPILATION_INFO)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_gpu_shader_compilation_info(
                    binding, out, handle, timeoutns,
                )
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_gpu_shader_compilation_info(
                    binding, out, handle, timeoutns,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: GpuCompilationInfo = unsafe { out.read() };
                let result_recorded_messages_slice = unsafe { result_value.messages.as_slice()? };
                let mut result_recorded_messages =
                    Vec::with_capacity(result_recorded_messages_slice.len());
                for result_recorded_messages_item in result_recorded_messages_slice.iter().cloned()
                {
                    let result_recorded_messages_item_recorded_kind =
                        result_recorded_messages_item.kind;
                    let result_recorded_messages_item_recorded_message =
                        unsafe { result_recorded_messages_item.message.as_str()? }.to_string();
                    let result_recorded_messages_item_recorded_line =
                        result_recorded_messages_item.line;
                    let result_recorded_messages_item_recorded_column =
                        result_recorded_messages_item.column;
                    let result_recorded_messages_item_recorded_offset =
                        result_recorded_messages_item.offset;
                    let result_recorded_messages_item_recorded_length =
                        result_recorded_messages_item.length;
                    let result_recorded_messages_item_recorded =
                        GpucompilationmessageReplayRecord {
                            kind: result_recorded_messages_item_recorded_kind,
                            message: result_recorded_messages_item_recorded_message,
                            line: result_recorded_messages_item_recorded_line,
                            column: result_recorded_messages_item_recorded_column,
                            offset: result_recorded_messages_item_recorded_offset,
                            length: result_recorded_messages_item_recorded_length,
                        };
                    result_recorded_messages.push(result_recorded_messages_item_recorded);
                }
                let result_recorded = GpucompilationinfoReplayRecord {
                    messages: result_recorded_messages,
                };
                let payload = GpuPipelineShaderCompilationInfoReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    GpuPipelineShaderCompilationInfoReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_messages = binding.store_slice_with(
                        value.messages.len(),
                        |value_native_messages_values| {
                            for value_native_messages_item in value.messages {
                                let value_native_messages_decoded_kind =
                                    value_native_messages_item.kind;
                                let value_native_messages_decoded_message =
                                    binding.store_string_owned(value_native_messages_item.message);
                                let value_native_messages_decoded_line =
                                    value_native_messages_item.line;
                                let value_native_messages_decoded_column =
                                    value_native_messages_item.column;
                                let value_native_messages_decoded_offset =
                                    value_native_messages_item.offset;
                                let value_native_messages_decoded_length =
                                    value_native_messages_item.length;
                                let value_native_messages_decoded = GpuCompilationMessage {
                                    kind: value_native_messages_decoded_kind,
                                    message: value_native_messages_decoded_message,
                                    line: value_native_messages_decoded_line,
                                    column: value_native_messages_decoded_column,
                                    offset: value_native_messages_decoded_offset,
                                    length: value_native_messages_decoded_length,
                                };
                                value_native_messages_values.push(value_native_messages_decoded);
                            }
                            Ok(())
                        },
                    )?;
                    let value_native = GpuCompilationInfo {
                        messages: value_native_messages,
                    };
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

