#[inline]
fn destack_gpu_device_has_feature_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    device: resource::GpuDeviceHandle,
    feature: GpuFeatureId,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        GPU_DEVICE_HAS_FEATURE,
        binding.replay_payload_for(GPU_DEVICE_HAS_FEATURE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_gpu_device_has_feature(binding, context, device, feature)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_gpu_device_has_feature(
                binding, context, device, feature,
            ),
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: bool = value.clone();
                let result_recorded = result_value;
                let payload = GpuDeviceHasFeatureReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    GpuDeviceHasFeatureReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_gpu_device_has_feature_result(context, result)?;
    Ok(result)
}

